const item = $input.first();
const data = item.json;
if (data.IsErroredOnProcessing) {
  const msg = Array.isArray(data.ErrorMessage) ? data.ErrorMessage.join(' ') : (data.ErrorMessage || 'OCR failed');
  throw new Error(msg);
}
const text = (data.ParsedResults || []).map(p => p.ParsedText || '').filter(Boolean).join('\n\n').trim();
if (!text) throw new Error('No text extracted from document');
return [{ json: { documentText: text.slice(0, 120000) } }];

