={
  "contents": [{
    "role": "user",
    "parts": [{
      "text": "You are a legal document analyst for LawPal (Pakistan / Punjab focus). Analyze the legal document and return ONLY one valid JSON object with keys explanation, urdu, sections, glossary.\n\nStrict rules:\n- explanation / urdu: overall document summary only.\n- sections: ONLY real sections/clauses/articles from the document. Each item is {title, content} where title is the section heading and content explains THAT section. Do NOT put glossary terms, definitions, parties, dates, or advice in sections.\n- glossary: ONLY legal vocabulary terms as {term, definition}. Do NOT put section numbers, clause explanations, summaries, or advice in glossary.\n- Never duplicate content across sections and glossary.\n- Return 4-8 sections (or fewer if fewer real sections) and 5-10 glossary terms.\n- Keep strings on single lines.\n\nDocument:\n" + $json.documentText
    }]
  }],
  "generationConfig": {
    "temperature": 0.2,
    "maxOutputTokens": 4096,
    "responseMimeType": "application/json"
  }
}

