const data = $input.first().json;
const raw = (data.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('').trim();
if (!raw) throw new Error('Empty Gemini response');
let cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const parsed = JSON.parse(cleaned);
const sections = (Array.isArray(parsed.sections) ? parsed.sections : []).map((s) => ({ title: String(s?.title || s?.name || s?.heading || '').trim(), content: String(s?.content || s?.explanation || s?.text || '').trim() })).filter((s) => s.title && s.content).filter((s) => !/^(glossary|definition|term)\b/i.test(s.title));
const glossary = (Array.isArray(parsed.glossary) ? parsed.glossary : []).map((g) => ({ term: String(g?.term || g?.word || g?.title || '').trim(), definition: String(g?.definition || g?.meaning || g?.content || '').trim() })).filter((g) => g.term && g.definition).filter((g) => !/^(section|clause|article|chapter)\s*\d+/i.test(g.term));
return [{ json: { success: true, explanation: typeof parsed.explanation === 'string' ? parsed.explanation : '', urdu: typeof parsed.urdu === 'string' ? parsed.urdu : '', sections, glossary } }];
